package com.bookreads.ui.home

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class HomeViewModel(
    private val navigationCallback: HomeNavigationCallback,
) : ViewModel() {
    val viewState: StateFlow<HomeViewState>
        field = MutableStateFlow<HomeViewState>(HomeViewState.Idle)

    fun onEvent(event: HomeViewEvent) {
        when (event) {
            is HomeViewEvent.EnterUsername -> viewModelScope.launch {
                navigationCallback.goToSession(event.username)
            }
        }
    }
}
```

