package com.bookreads.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.mutableStateListOf
import androidx.navigation3.runtime.NavKey
import androidx.navigation3.runtime.entryProvider
import androidx.navigation3.ui.NavDisplay
import com.bookreads.ui.common.AppTheme
import com.bookreads.ui.home.HomeScreen
import com.bookreads.ui.leaderboard.LeaderboardScreen
import com.bookreads.ui.session.SessionScreen
import org.koin.compose.getKoin
import org.koin.core.parameter.parametersOf

@Composable
fun NavApp() =
    AppTheme {
        val koin = getKoin()
        val backStack = mutableStateListOf<NavKey>(AppRoutes.Home)
        val appNavigation = AppNavigation(backStack = backStack)
        NavDisplay(
            backStack = backStack,
            onBack = { backStack.removeLastOrNull() },
            entryProvider =
                entryProvider {
                    entry<AppRoutes.Home> {
                        HomeScreen {
                            koin.get { parametersOf(appNavigation) }
                        }
                    }
                    entry<AppRoutes.Session> { key ->
                        SessionScreen {
                            koin.get { parametersOf(key.username, appNavigation) }
                        }
                    }
                    entry<AppRoutes.Leaderboard> {
                        LeaderboardScreen {
                            koin.get { parametersOf(appNavigation) }
                        }
                    }
                },
        )
    }
```

